const byCode = new Map<string, Language>(LANGUAGES.map((l) => [l.code, l]));
// Codes a model may answer with: the alternates Google lists for the same language, in any letter case.
// (Maps, not objects: a model may answer "constructor" and an object lookup would find Object.prototype's.)
const ALIAS = new Map([["zh", "zh-cn"], ["iw", "he"], ["tl", "fil"], ["jw", "jv"]]);
const byLower = new Map<string, Language>(LANGUAGES.map((l) => [l.code.toLowerCase(), l]));
const find = (code: string) => {
  const lower = code.toLowerCase();
  return byCode.get(code) ?? byLower.get(ALIAS.get(lower) ?? lower);
};

// Strict: used to validate what a client sends. Aliases are for display only.
export const isLang = (code: string): boolean => byCode.has(code);

// Thai name for the UI; an unknown code (e.g. the model answered "und") is shown as is.
export const langName = (code: string): string => find(code)?.th ?? code;

// English name for the model prompt.
export const langEnglish = (code: string): string => find(code)?.en ?? code;

// Names that start with the query first, then names that contain it; each group keeps the Thai-name order.
// Thai, English and the code all count for a prefix match; only the names count for "contains".
export function searchLanguages(q: string): Lang[] {
  const s = q.trim().toLowerCase();
  if (!s) return LANGUAGES.map((l) => l.code);
  const starts: Lang[] = [];
  const contains: Lang[] = [];
  for (const { code, th, en } of LANGUAGES) {
    const names = [th, en.toLowerCase()];
    if (code.toLowerCase().startsWith(s) || names.some((n) => n.startsWith(s))) starts.push(code);
    else if (names.some((n) => n.includes(s))) contains.push(code);
  }
  return [...starts, ...contains];
}
